MRCEM_TOPICS = MRCEM_PART1 + MRCEM_PART2 + MRCEM_PART3 + MRCEM_PART4

def main():
    print(f"Total FCPS Topics: {len(FCPS_TOPICS)}")
    print(f"Total NLE Topics: {len(NLE_TOPICS)}")
    print(f"Total MRCEM Topics: {len(MRCEM_TOPICS)}")
    assert len(FCPS_TOPICS) == 100, f"Expected 100 FCPS topics, got {len(FCPS_TOPICS)}"
    assert len(NLE_TOPICS) == 100, f"Expected 100 NLE topics, got {len(NLE_TOPICS)}"
    assert len(MRCEM_TOPICS) == 100, f"Expected 100 MRCEM topics, got {len(MRCEM_TOPICS)}"

    from build_mega38_b import TAXONOMY_SUBJECTS, TAXONOMY_SYSTEMS
    for t in FCPS_TOPICS + NLE_TOPICS + MRCEM_TOPICS:
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject: {t[1]} in {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system: {t[2]} in {t[0]}"
        assert t[5].startswith("https://"), f"Invalid URL: {t[5]} in {t[0]}"

    out_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "mega38_topics_b.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Generated Mega-Batch 38 Topics Part B\n")
        f.write("# FCPS (100 topics) + NLE (100 topics) + MRCEM (100 topics)\n\n")
        f.write(f"FCPS_TOPICS = {repr(FCPS_TOPICS)}\n\n")
        f.write(f"NLE_TOPICS = {repr(NLE_TOPICS)}\n\n")
        f.write(f"MRCEM_TOPICS = {repr(MRCEM_TOPICS)}\n")
    print(f"Successfully generated {out_path}")

if __name__ == "__main__":
    main()
